CREATE TABLE IF NOT EXISTS asset_risk_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, assessment_version text NOT NULL DEFAULT '1.0', overall_score numeric(6,2), integrity_score numeric(6,2), investment_readiness_score numeric(6,2), overall_rating text NOT NULL DEFAULT 'Unrated', decision text NOT NULL DEFAULT 'Pending', assessed_at timestamptz NOT NULL DEFAULT now(), assessor_reference text, methodology text NOT NULL DEFAULT 'Evidence-gated multi-domain assessment', decision_basis text, status text NOT NULL DEFAULT 'Draft');
CREATE TABLE IF NOT EXISTS asset_risk_dimensions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid REFERENCES asset_risk_assessments(id) ON DELETE CASCADE, dimension_code text NOT NULL, dimension_name text NOT NULL, score numeric(6,2), rating text NOT NULL DEFAULT 'Unrated', confidence_score numeric(6,2), evidence_count integer NOT NULL DEFAULT 0, verified_evidence_count integer NOT NULL DEFAULT 0, key_findings text, blocking_factors text, status text NOT NULL DEFAULT 'Assessed');
CREATE TABLE IF NOT EXISTS asset_risk_factors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid REFERENCES asset_risk_assessments(id) ON DELETE CASCADE, dimension_code text NOT NULL, factor_code text NOT NULL, severity text NOT NULL DEFAULT 'Medium', likelihood text NOT NULL DEFAULT 'Possible', score numeric(8,2), finding text NOT NULL, evidence_reference text, mitigation text, residual_risk text, status text NOT NULL DEFAULT 'Open');
CREATE TABLE IF NOT EXISTS asset_intelligence_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid REFERENCES continental_assets(id) ON DELETE CASCADE, assessment_id uuid REFERENCES asset_risk_assessments(id) ON DELETE SET NULL, decision_type text NOT NULL, decision text NOT NULL, rationale text NOT NULL, blocking_factor_count integer NOT NULL DEFAULT 0, confidence_score numeric(6,2), decided_by_reference text, decided_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'Recorded');
CREATE INDEX IF NOT EXISTS idx_asset_risk_asset ON asset_risk_assessments(asset_id,assessed_at DESC);
CREATE INDEX IF NOT EXISTS idx_asset_risk_dimensions_assessment ON asset_risk_dimensions(assessment_id);
CREATE INDEX IF NOT EXISTS idx_asset_risk_factors_assessment ON asset_risk_factors(assessment_id);